package androidwhatsapp_test

import (
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/androidwhatsapp"
	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

// The scenario oracle is generated by tools/fixtures/whatsapp_gen.py: an implementation of the spec's rules in another
// language that shares no Go code with the parser (it restates the purge and attachment logic, so it is a second reading of
// the spec, not an independent source of truth; oracle_facts_test.go states the spec's facts literally): every record, warning and note it states must be what Parse produces. A variant that is reported unparsed
// (a backup, an encrypted file, neither table) states no generation and is covered by the probe tests.
func TestWhatsAppMatchesOracle(t *testing.T) {
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		if fx.Expect.Notes["generation"] == "" {
			continue
		}
		t.Run(v, func(t *testing.T) {
			h := parsertest.NewHarness(t)
			b := fx.Bundle(h, remoteFor(v))
			p := androidwhatsapp.Parser{}
			res := h.RunLenient(p, b.Input(h, p, false))
			parsertest.AssertMatchesOracle(t, res, b, fx.Expect)
		})
	}
}
